The restaurant also caters for private parties, birthdays and corporate functions, making it an option for groups booking a function alongside its regular a la carte service. Moksh Indian Restaurant trades from the FNB Building on Main Road in Plumstead, Cape Town, and takes reservations. It suits families, groups and anyone after North Indian cuisine for a casual meal or a booked function in the southern suburbs.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://mokshrestaurants.com/plumstead/', '$[#]', 'https://www.tripadvisor.com/Restaurant_Review-g6776488-d33219893-Reviews-Moksh_Indian_Restaurant_Plumstead-Plumstead_Western_Cape.html'), description_enriched_at = datetime('now') WHERE slug = 'moksh-indian-restaurant-plumstead' AND description = 'Moksh Indian Restaurant is a North Indian restaurant in Plumstead specialising in tandoor-cooked dishes and curries prepared by chefs trained in India, also catering for private functions and family celebrations.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
