UPDATE businesses SET description = 'Montague Gardens Hardware and Steel is a hardware and steel fabrication business at 20 Montague Drive in Montague Gardens, Cape Town, founded in 1976. It began as a modest woodworking workshop and has expanded over the decades into steel fabrication, becoming the business known today.

The company sits in Cape Town''s Montague Gardens industrial precinct, prized for its location near the N1 and N7 highways and its proximity to Cape Town International Airport, surrounded by other established businesses and distribution hubs. Its range covers hardware and DIY essentials, including tools, galvanised pipe fittings, stainless-steel bolts and nuts, safety gear, drill bits and garden kits. It suits tradespeople and DIY customers who need hardware supplies alongside custom steel fabrication work.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://mghw.co.za/about-us'), description_enriched_at = datetime('now') WHERE slug = 'montague-gardens-hardware-and-steel-montague-gardens' AND description = 'Montague Gardens Hardware & Steel is a hardware and steel fabrication business in Montague Gardens, offering DIY tools, steel fittings, safety gear and custom steel fabrication services, trading since 1976.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
